-- Global LibreVita schema (SQLite).
-- Domain tables and triggers are defined here.
-- This is the schema source for sqlc (see sqlc.yaml).
-- Keep in sync with db/migrations/00002_auth.sql.
-- Primary keys are UUIDv7 TEXT generated by the application.

-- Relational roles: the account role is a row in roles instead of a
-- fixed TEXT CHECK enum. See db/migrations/00011_roles.sql.
CREATE TABLE roles (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE COLLATE NOCASE,
    system      INTEGER NOT NULL DEFAULT 0 CHECK (system IN (0, 1)),
    is_clinical INTEGER NOT NULL DEFAULT 0 CHECK (is_clinical IN (0, 1)),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE users (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE COLLATE nocase,
    password_hash TEXT NOT NULL,
    display_name TEXT NOT NULL,
    role_id TEXT NOT NULL REFERENCES roles(id),
    active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_users_role ON users (role_id);

-- Server-side session revocation index, owned by internal/core/auth.
CREATE TABLE sessions (
    token_hash TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at TEXT NOT NULL
);

-- Durable audit trail, owned by internal/core/audit.
-- See db/migrations/00003_audit.sql.
CREATE TABLE audit_log (
id          INTEGER PRIMARY KEY AUTOINCREMENT,
actor_id    TEXT,
actor_email TEXT,
action      TEXT    NOT NULL,
resource    TEXT    NOT NULL,
result      TEXT    NOT NULL CHECK (result IN ('success', 'failure')),
ip          TEXT,
request_id  TEXT,
detail      TEXT,
created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Clinic profile created during onboarding, owned by the clinic domain,
-- and the system metadata table. See db/migrations/00004_onboarding.sql.
CREATE TABLE clinics (
id          TEXT    PRIMARY KEY,
name        TEXT    NOT NULL,
tax_id      TEXT,
phone       TEXT,
email       TEXT,
street      TEXT,
city        TEXT,
state       TEXT,
postal_code TEXT,
country     TEXT    NOT NULL DEFAULT 'BR',
timezone    TEXT    NOT NULL DEFAULT 'America/Sao_Paulo',
created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE meta (
key        TEXT    PRIMARY KEY,
value      TEXT    NOT NULL,
updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Dynamic CEL authorization policies, owned by internal/core/policy.
-- See db/migrations/00005_policy.sql and 00006_policy_version.sql.
CREATE TABLE policies (
id         TEXT    PRIMARY KEY,
name       TEXT    NOT NULL UNIQUE,
expression TEXT    NOT NULL,
updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE policy_versions (
id               INTEGER PRIMARY KEY AUTOINCREMENT,
policy_id        TEXT    NOT NULL REFERENCES policies(id) ON DELETE RESTRICT,
expression       TEXT    NOT NULL,
changed_by       TEXT,
changed_by_email TEXT,
origin           TEXT    NOT NULL DEFAULT 'system'
CHECK (origin IN ('seed', 'admin', 'system')),
created_at       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ',
'now'))
);

CREATE TABLE patients (
    id          TEXT    PRIMARY KEY,
    clinic_id   TEXT    NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    display_name TEXT   NOT NULL,
    birth_date  TEXT,
    sex         TEXT    NOT NULL DEFAULT 'unknown'
                        CHECK (sex IN ('female', 'male', 'other', 'unknown')),
    document    TEXT,
    phone       TEXT,
    email       TEXT,
    street      TEXT,
    city        TEXT,
    state       TEXT,
    postal_code TEXT,
    notes       TEXT,
    status      TEXT    NOT NULL DEFAULT 'active'
                        CHECK (status IN ('active', 'inactive')),
    created_by  TEXT    REFERENCES users(id),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_patients_clinic ON patients (clinic_id);
CREATE INDEX idx_patients_name ON patients (display_name COLLATE NOCASE);
CREATE UNIQUE INDEX idx_patients_clinic_document
    ON patients (clinic_id, document)
    WHERE document IS NOT NULL;

-- Clinician specialties and their mapping to users. Owned by the user
-- domain; see db/migrations/00009_specialties.sql.
CREATE TABLE specialties (
    id         TEXT PRIMARY KEY,
    clinic_id  TEXT NOT NULL,
    name       TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE UNIQUE INDEX idx_specialties_clinic_name
    ON specialties (clinic_id, name COLLATE NOCASE);

CREATE TABLE user_specialties (
    user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    specialty_id TEXT NOT NULL REFERENCES specialties(id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, specialty_id)
);

CREATE INDEX idx_user_specialties_specialty ON user_specialties (specialty_id);

-- Staff profile change requests: receptionist proposals that an admin
-- approves or rejects. Owned by the user domain; see
-- db/migrations/00010_staff_requests.sql.
CREATE TABLE staff_change_requests (
    id            TEXT PRIMARY KEY,
    user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    requested_by  TEXT NOT NULL REFERENCES users(id),
    status        TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'approved', 'rejected')),
    changes       TEXT NOT NULL,
    decision_note TEXT,
    created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    decided_at    TEXT,
    decided_by    TEXT REFERENCES users(id)
);

CREATE INDEX idx_staff_requests_status ON staff_change_requests (status, created_at DESC);
CREATE INDEX idx_staff_requests_user ON staff_change_requests (user_id);
